DROP TABLE IF EXISTS `PRODUCTOS`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `PRODUCTOS` (
  `ID` smallint DEFAULT NULL,
  `CODIGO` varchar(20) DEFAULT NULL,
  `DESCRIPCION` varchar(43) DEFAULT NULL,
  `TVENTA` varchar(1) DEFAULT NULL,
  `PCOSTO` decimal(5,3) DEFAULT NULL,
  `PVENTA` decimal(6,4) DEFAULT NULL,
  `DEPT` tinyint DEFAULT NULL,
  `PROVID` varchar(2) DEFAULT NULL,
  `UMEDIDA` int DEFAULT NULL,
  `MAYOREO` decimal(7,4) DEFAULT NULL,
  `IPRIORIDAD` varchar(1) DEFAULT NULL,
  `DINVENTARIO` varchar(7) DEFAULT NULL,
  `DINVMINIMO` varchar(3) DEFAULT NULL,
  `DINVMAXIMO` varchar(3) DEFAULT NULL,
  `CHECADO_EN` varchar(19) DEFAULT NULL,
  `PORCENTAJE_GANANCIA` decimal(5,2) DEFAULT NULL,
  `COMPONENTES` varchar(16) DEFAULT NULL,
  `IMPUESTOS` varchar(3) DEFAULT NULL,
  `PVENTA_ANTERIOR` varchar(6) DEFAULT NULL,
  `PCOSTO_ANTERIOR` varchar(5) DEFAULT NULL,
  `PMAYOREO_ANTERIOR` varchar(6) DEFAULT NULL,
  `MEDIDA_ID` tinyint DEFAULT NULL,
  `PFINAL` decimal(5,3) DEFAULT NULL,
  `PMAYOREOFINAL` decimal(6,3) DEFAULT NULL,
  `ES_KIT` varchar(1) DEFAULT NULL,
  `USA_INVENTARIO` varchar(1) DEFAULT NULL,
  `ELIMINADO_EN` varchar(19) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;
